import numpy as np
import matplotlib.pyplot as plt
from scipy.special import lambertw
from scipy.integrate import solve_ivp
from scipy.linalg import expm
from scipy.optimize import brentq
plt.rcParams['axes.unicode_minus'] = False
a,k=1.,2.
wc=np.sqrt(k*k-a*a);tc=np.arccos(-a/k)/wc
tsg=2/np.sqrt(4*k*k-(a+k)**2)
def dde(a,k,tau,times,rtol=1e-10):
    times=np.asarray(times);end=float(times[-1])
    if tau==0:return np.exp(-(a+k)*times)
    solutions=[];ends=[];state=1.
    def history(t):
        if t<=1e-12:return 1.
        j=min(int(np.searchsorted(ends,t,side='left')),len(solutions)-1)
        return float(solutions[j](t)[0])
    for n in range(int(np.ceil(end/tau))):
        left=n*tau;right=min(end,(n+1)*tau)
        sol=solve_ivp(lambda t,x:[-a*x[0]-k*history(t-tau)],(left,right),[state],method='DOP853',dense_output=True,rtol=rtol,atol=rtol*.01,max_step=min(.05,tau))
        assert sol.success
        solutions.append(sol.sol);ends.append(right);state=float(sol.y[0,-1])
    return np.array([1. if t==0 else float(solutions[min(int(np.searchsorted(ends,t,side='left')),len(solutions)-1)](t)[0]) for t in times])
def pade_trace(a,k,tau,times):
    if tau==0:return np.exp(-(a+k)*np.asarray(times))
    A=np.array([[k-a,-2*k],[2/tau,-2/tau]])
    return np.array([(expm(A*t)@np.ones(2))[0] for t in times])

